import shutil
import re
import openpyxl

if INIT != OUT:
    shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

sheet_name = "Sheet1"
if sheet_name not in wb.sheetnames:
    ws = wb.create_sheet(sheet_name)
else:
    ws = wb[sheet_name]

vws = vals[sheet_name] if sheet_name in vals.sheetnames else None

def is_blank(v):
    return v is None or (isinstance(v, str) and v.strip() == "")

def suffix_to_int(s):
    n = 0
    for ch in s.lower():
        n = n * 26 + (ord(ch) - ord("a") + 1)
    return n

def int_to_suffix(n):
    if n <= 0:
        return ""
    s = ""
    while n > 0:
        n -= 1
        s = chr(ord("a") + (n % 26)) + s
        n //= 26
    return s

def parse_urn(v):
    if is_blank(v):
        return None
    if isinstance(v, bool):
        return None
    if isinstance(v, int):
        return (v, 0)
    if isinstance(v, float):
        if v.is_integer():
            return (int(v), 0)
        return None

    s = str(v).strip()
    m = re.match(r"^(\d+)([a-zA-Z]+)$", s)
    if m:
        return (int(m.group(1)), suffix_to_int(m.group(2)))
    m = re.match(r"^(\d+)$", s)
    if m:
        return (int(m.group(1)), 0)
    return None

data_max_row = 1
if vws is not None:
    for r in range(1, vws.max_row + 1):
        a = vws.cell(row=r, column=1).value
        b = vws.cell(row=r, column=2).value
        if not is_blank(a) or not is_blank(b):
            data_max_row = r

current_base = None
current_next = 1
filled = 0

for r in range(2, data_max_row + 1):
    a = vws.cell(row=r, column=1).value
    b = vws.cell(row=r, column=2).value

    if is_blank(a):
        if current_base is not None and not is_blank(b):
            label = f"{current_base}{int_to_suffix(current_next)}"
            ws.cell(row=r, column=1).value = label
            current_next += 1
            filled += 1
        else:
            ws.cell(row=r, column=1).value = None
    else:
        if isinstance(a, str):
            a_out = a.strip()
        elif isinstance(a, float) and a.is_integer():
            a_out = int(a)
        else:
            a_out = a

        ws.cell(row=r, column=1).value = a_out

        parsed = parse_urn(a)
        if parsed is not None:
            current_base, suffix = parsed
            current_next = suffix + 1
        else:
            current_base = None
            current_next = 1

if data_max_row < 90:
    for r in range(data_max_row + 1, 91):
        ws.cell(row=r, column=1).value = None
        ws.cell(row=r, column=2).value = None

print("data_max_row:", data_max_row, "filled:", filled)
print("samples:", [(r, ws.cell(row=r, column=1).value) for r in (14, 18, 23, 45, 52, 79) if r <= data_max_row])

wb.save(OUT)
